'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { Search, ArrowRight, Store, Sparkles } from 'lucide-react';
import { Profile } from '@/lib/db';

export default function ExplorePage() {
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [realProfiles, setRealProfiles] = useState<Profile[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const demoStorefronts = [
    {
      handle: 'mayastudio',
      displayName: 'Maya Lin Studio',
      bio: 'Minimalist motion designer & photographer crafting UI kits and typography masterclasses.',
      category: 'Design',
      accentColor: '#D4E157',
      productCount: 3,
      salesCount: 42,
      avatarUrl: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80',
    },
    {
      handle: 'alexvance',
      displayName: 'Alex Vance',
      bio: 'Landscape & portrait photographer releasing signature RAW Lightroom presets.',
      category: 'Photography',
      accentColor: '#A4B87C',
      productCount: 5,
      salesCount: 88,
      avatarUrl: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80',
    },
  ];

  useEffect(() => {
    async function fetchExploreData() {
      try {
        const res = await fetch('/api/explore');
        if (res.ok) {
          const data = await res.json();
          // Filter out demo handles from real list if present
          const realOnly = (data.profiles || []).filter(
            (p: Profile) => p.handle !== 'mayastudio' && p.handle !== 'alexvance'
          );
          setRealProfiles(realOnly);
        }
      } catch (err) {
        console.error('Error fetching explore profiles:', err);
      } finally {
        setIsLoading(false);
      }
    }
    fetchExploreData();
  }, []);

  const categories = ['All', 'Design', 'Photography', 'Audio', 'Code', 'Education'];

  const filteredReal = realProfiles.filter((s) => {
    const matchesSearch = s.displayName.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          s.handle.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          (s.bio || '').toLowerCase().includes(searchQuery.toLowerCase());
    return matchesSearch;
  });

  const filteredDemo = demoStorefronts.filter((s) => {
    const matchesCategory = selectedCategory === 'All' || s.category === selectedCategory;
    const matchesSearch = s.displayName.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          s.handle.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          s.bio.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="ambient-bg-wash" style={{ minHeight: '100vh', paddingBottom: '100px' }}>
      {/* Navigation Header */}
      <nav style={{ padding: '20px 0', borderBottom: '1px solid var(--border-light)' }}>
        <div className="container" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Link href="/" style={{ textDecoration: 'none', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{
              width: '32px', height: '32px', backgroundColor: 'var(--bg-dark)', borderRadius: '6px',
              display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--accent-primary)',
              fontFamily: 'var(--font-display)', fontSize: '18px', fontWeight: 700, fontStyle: 'italic'
            }}>
              A
            </div>
            <span className="font-display" style={{ fontSize: '1.4rem', fontWeight: 600 }}>Atelier</span>
          </Link>
          <Link href="/create" className="btn btn-olive btn-sm">
            Open Storefront
          </Link>
        </div>
      </nav>

      {/* Header Area with Market Image */}
      <div style={{ position: 'relative', overflow: 'hidden', marginBottom: '40px' }}>
        <div style={{
          height: '220px', width: '100%',
          WebkitMaskImage: 'linear-gradient(to bottom, black 50%, transparent 100%)',
          maskImage: 'linear-gradient(to bottom, black 50%, transparent 100%)'
        }}>
          <img src="/images/explore_header_market.jpg" alt="Creative Market Header" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </div>

        <div className="container" style={{ position: 'relative', marginTop: '-110px', textAlign: 'center' }}>
          <span className="eyebrow" style={{ display: 'inline-block', marginBottom: '12px' }}>DIRECTORY</span>
          <h1 className="font-display" style={{ fontSize: 'clamp(1.8rem, 5vw, 2.8rem)', marginBottom: '16px' }}>
            Explore Atelier Storefronts
          </h1>
          <p style={{
            fontSize: '1.05rem', fontWeight: 300, color: 'var(--text-secondary)',
            letterSpacing: '-0.01em', maxWidth: '560px', margin: '0 auto 32px auto'
          }}>
            Discover digital products, design systems, presets, audio samples, and code from independent creators.
          </p>

          {/* Search Bar */}
          <div style={{ maxWidth: '480px', margin: '0 auto 32px auto', position: 'relative' }}>
            <Search size={18} color="var(--text-tertiary)" style={{ position: 'absolute', left: '16px', top: '14px' }} />
            <input
              type="text"
              placeholder="Search creators, presets, templates..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                width: '100%', padding: '12px 16px 12px 48px', borderRadius: '100px',
                border: '1px solid var(--border-medium)', fontSize: '0.9rem',
                backgroundColor: '#FFFFFF', boxShadow: 'var(--shadow-sm)'
              }}
            />
          </div>

          {/* Category Pills */}
          <div style={{ display: 'flex', gap: '8px', justifyContent: 'center', flexWrap: 'wrap' }}>
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className="btn btn-sm"
                style={{
                  backgroundColor: selectedCategory === cat ? 'var(--accent-olive)' : 'var(--bg-card)',
                  color: selectedCategory === cat ? '#FFFFFF' : 'var(--text-secondary)',
                  border: '1px solid var(--border-medium)',
                  fontSize: '0.82rem'
                }}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Main Content Areas */}
      <div className="container">
        {/* SECTION 1: REAL STOREFRONTS */}
        {filteredReal.length > 0 && (
          <div style={{ marginBottom: '48px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '20px' }}>
              <Sparkles size={20} color="var(--accent-olive)" />
              <h2 style={{ fontSize: '1.4rem' }}>Live Creator Storefronts</h2>
            </div>
            <div className="grid-three-col" style={{ gap: '28px' }}>
              {filteredReal.map((s) => (
                <Link key={s.handle} href={`/${s.handle}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                  <div className="card glow-hover" style={{ padding: '28px', height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', borderTop: `4px solid ${s.accentColor || '#D4E157'}` }}>
                    <div>
                      <div style={{ display: 'flex', gap: '16px', alignItems: 'center', marginBottom: '16px' }}>
                        <img src={s.avatarUrl || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80'} alt={s.displayName} style={{ width: '50px', height: '50px', borderRadius: '50%', objectFit: 'cover' }} />
                        <div>
                          <h3 style={{ fontSize: '1.15rem', marginBottom: '2px' }}>{s.displayName}</h3>
                          <span className="font-mono" style={{ fontSize: '0.78rem', color: 'var(--text-tertiary)' }}>@{s.handle}</span>
                        </div>
                      </div>
                      <p style={{ fontSize: '0.88rem', color: 'var(--text-secondary)', lineHeight: 1.6, marginBottom: '20px' }}>
                        {s.bio || 'Digital goods creator on Nimiq Pay.'}
                      </p>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '16px', borderTop: '1px solid var(--border-light)' }}>
                      <span className="font-mono" style={{ fontSize: '0.78rem', color: 'var(--accent-olive)', fontWeight: 600 }}>
                        {s.productCount || 0} PRODUCTS • {s.totalSales || 0} SALES
                      </span>
                      <span style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '0.82rem', fontWeight: 600 }}>
                        Visit <ArrowRight size={14} />
                      </span>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        )}

        {/* SECTION 2: DEMO STOREFRONTS DIVIDER & LIST */}
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', margin: '32px 0 20px 0' }}>
            <span className="eyebrow" style={{ color: 'var(--text-tertiary)', fontSize: '0.75rem', whiteSpace: 'nowrap' }}>
              DEMO STOREFRONTS
            </span>
            <div style={{ height: '1px', backgroundColor: 'var(--border-medium)', flex: 1 }} />
          </div>

          <div className="grid-three-col" style={{ gap: '28px' }}>
            {filteredDemo.map((s) => (
              <Link key={s.handle} href={`/${s.handle}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                <div className="card glow-hover" style={{ padding: '28px', height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', borderTop: `4px solid ${s.accentColor}` }}>
                  <div>
                    <div style={{ display: 'flex', gap: '16px', alignItems: 'center', marginBottom: '16px' }}>
                      <img src={s.avatarUrl} alt={s.displayName} style={{ width: '50px', height: '50px', borderRadius: '50%', objectFit: 'cover' }} />
                      <div>
                        <h3 style={{ fontSize: '1.15rem', marginBottom: '2px' }}>{s.displayName}</h3>
                        <span className="font-mono" style={{ fontSize: '0.78rem', color: 'var(--text-tertiary)' }}>@{s.handle}</span>
                      </div>
                    </div>
                    <p style={{ fontSize: '0.88rem', color: 'var(--text-secondary)', lineHeight: 1.6, marginBottom: '20px' }}>
                      {s.bio}
                    </p>
                  </div>

                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '16px', borderTop: '1px solid var(--border-light)' }}>
                    <span className="font-mono" style={{ fontSize: '0.78rem', color: 'var(--accent-olive)', fontWeight: 600 }}>
                      {s.productCount} PRODUCTS • {s.salesCount} SALES
                    </span>
                    <span style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '0.82rem', fontWeight: 600 }}>
                      Visit <ArrowRight size={14} />
                    </span>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
